type PortfolioItem = {
  title: string;
  image: string;
  duration: string;
  material: string;
  format: string;
};

type PortfolioProps = {
  items: PortfolioItem[];
};

export default function Portfolio({ items }: PortfolioProps) {
  return (
    <section className="py-16 sm:py-20 lg:py-24">
      <div className="mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8">
        <div className="flex items-center gap-4">
          <div className="h-px w-10 bg-gold/60" aria-hidden="true" />
          <h2 className="font-heading text-3xl font-semibold sm:text-4xl">
            Наши работы
          </h2>
        </div>
      </div>

      <div className="mt-10 overflow-x-auto pb-4">
        <div className="mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8">
          <div className="flex gap-5 snap-x snap-mandatory scroll-px-4 sm:gap-6 sm:scroll-px-6 lg:scroll-px-8">
            {items.map((item) => (
              <article
                key={item.title}
                className="group min-w-[260px] flex-1 snap-start overflow-hidden rounded-3xl border border-gold/25 bg-white/40"
              >
                <div className="relative h-48 w-full overflow-hidden sm:h-56">
                  <img
                    src={item.image}
                    alt={item.title}
                    className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.04]"
                    loading="lazy"
                  />
                </div>
                <div className="space-y-4 p-6">
                  <h3 className="font-heading text-lg font-semibold">{item.title}</h3>
                  <dl className="grid gap-3 text-sm text-anthracite/70">
                    <div className="flex items-center justify-between">
                      <dt className="text-anthracite/60">Срок</dt>
                      <dd>{item.duration}</dd>
                    </div>
                    <div className="flex items-center justify-between">
                      <dt className="text-anthracite/60">Материал</dt>
                      <dd>{item.material}</dd>
                    </div>
                    <div className="flex items-center justify-between">
                      <dt className="text-anthracite/60">Формат</dt>
                      <dd>{item.format}</dd>
                    </div>
                  </dl>
                </div>
              </article>
            ))}
          </div>
        </div>
      </div>

      <div className="mx-auto mt-8 w-full max-w-6xl px-4 sm:px-6 lg:px-8">
        <a
          href="#lead"
          className="focus-ring inline-flex rounded-full border border-gold/70 px-6 py-3 text-sm font-semibold text-anthracite transition hover:border-gold"
        >
          Хочу похожий проект
        </a>
      </div>
    </section>
  );
}
